    SIN: ['🦁', 'Lion City', [-28, 8, 'end']],
    ATH: ['🏛️', 'Ancient Castle City', [-6, -34, 'end']],
    IKA: ['🏖️', 'Island Paradise', [12, 50, 'middle']],
    KAL: ['🌊', 'Beach Days', [-28, 18, 'end']],
    NCE: ['🌅', 'Sunny Nice', [0, 50, 'middle']],
    PAR: ['🏰', 'Disney & the Eiffel Tower!', [30, 8, 'start']],
